          "ट्रैक शूज़ पर लापरवाही से न चढ़ें तथा जूते के सोल, सीढ़ी और हैंडल को तेल, ग्रीस व कीचड़ से पूरी तरह साफ रखें ताकि फिसलन न हो।",
          "केबिन विंडो, विंडशील्ड, रियर-व्यू कैमरा और दर्पणों को बिल्कुल साफ रखें ताकि स्पष्ट दृश्यता बनी रहे।",
          "सुरक्षा उपकरणों से छेड़छाड़ न करें, अग्निशामक यंत्र को सही स्थान पर रखें, और इलेक्ट्रॉनिक पार्ट्स पर सीधे पानी का छिड़काव न करें।"
