          "बाहरी सिग्नल की आवश्यकता होने पर अधिकृत सिग्नलमैन की जानकारी अधिकारी से लें और केवल उसी के इशारों का पालन करें। ऑपरेटर और सिग्नलर दोनों को संचालन संकेतों का सही ज्ञान होना अनिवार्य है।",
