          "Lighting Maintenance: Perform maintenance of the lighting circuit in accordance with the standard SOP.",
          "Panel Cleaning: Clean all HT/LT panels and circuits strictly according to the standard SOP.",
          "Earthing Check: Inspect and verify the continuity and integrity of the earthing circuit.",
          "Limit Switch Inspection: Check and test all limit switches for proper functionality.",
          "Pilot Tripping Test: Test and verify the pilot tripping mechanism on a quarterly basis.",
          "Emergency Alarm & Trip Test: Inspect and verify emergency tripping and the warning hooter quarterly.",
