          "Equipment Operability: Verify that the overall equipment is in a safe working condition before operation.",
          "Communication Check: Test the wireless radio system to ensure clear and effective communication.",
          "Cabin Facilities: Check and maintain all electrical facilities and controls inside the operator's cabin.",
          "Panel Enclosures: Ensure all panel cover boards are properly fitted and secured in place.",
