              "Magnetic Components: Inspect for signs of overheating, loose fixtures, and delamination.",
              "Cables & Interconnections: Inspect wiring for chafing, fraying, or thermal degradation, and ensure all PCB connectors are firmly seated.",
              "Printed Circuit Boards (PCBs): Inspect cleanliness and physical integrity; replace any boards displaying signs of deterioration."
