          "किसी भी प्रकार के नशे या मादक पदार्थों के प्रभाव में कार्यस्थल पर न आएं।",
          "कार्यस्थल की परिस्थितियों के अनुसार उपयुक्त अग्निशमन उपकरणों (Fire Fighting Provision) की व्यवस्था सुनिश्चित करें।"
