          "Power Disconnection: Disconnect the power supply cable to the lantern carriage before initiating any lowering operation.",
          "Powered Winch Operation: Utilize a remote pendant with a cable of sufficient length when lowering or lifting the lantern carriage via electric winch to maintain safe clearance from the mast.",
          "Manual Lowering/Lifting Precautions: For manual raising or lowering, ensure all lantern support brackets are secured in position, carriage movement is smooth, and the wire rope runs freely without jamming.",
          "Weather Conditions: Cease and avoid all lifting or lowering operations of the lantern carriage and mast during heavy winds.",
          "Qualified Crew Deployment: Execute mast lifting and lowering strictly using skilled, experienced technicians and certified crane operators.",
          "Pre-Lowering Isolation and Barricading: Barricade the entire perimeter around the mast, confirm no charged HT/LT overhead lines are located in the vicinity, and verify that all power supply and earthing connections to the tower are completely disconnected before lowering.",
          "Laydown Area Preparation: Ensure the designated surface area where the mast will rest after lowering is fully cleared, obstruction-free, and level.",
          "Mast Foundation Installation: Apply the exact same safety precautions, clearance checks, and barricading controls when hoisting and erecting the mast onto its foundation."
