    "guidelines": {
      "count": 4,
      "en": "General Guidelines",
      "hi": "सामान्य दिशानिर्देश"
    },
    "en": [
      [
        "Pre-Work Safety Briefing (Toolbox Talk)",
        [
          "Conduct a mandatory Safety Talk prior to starting any work.",
          "Discuss and identify the nature of the work along with all associated hazards.",
          "Identify and arrange the required Personal Protective Equipment (PPE).",
          "Identify and verify all necessary measuring equipment, tools, and tackles.",
          "Determine and confirm the specific shutdown procedure required for the work."
        ]
      ],
      [
        "Workplace Conduct and Emergency Preparedness",
        [
          "Do not use mobile phones while work is in progress.",
          "Reporting to work in an intoxicated condition is strictly prohibited.",
          "Ensure suitable fire-fighting provisions are readily available according to site conditions."
        ]
      ],
      [
        "Personal Protective Equipment (PPE) & Work Attire Requirements",
        [
          [
            "Wear mandatory and task-specific PPE based on job requirements and working conditions:",
            [
              "Safety shoes",
              "Safety helmet",
              "Hand gloves of suitable electrical rating",
              "Safety goggles",
              "Ear muffs",
              "Safety belt",
              "Arc flash suit",
              "Contactless HT/LT line tester",
              "Discharge rods"
            ]
          ],
          "Avoid wearing loose clothing when working around electrical systems.",
          "Do not wear any metallic items while working on electrical installations, including rings, bracelets, or wristwatches."
        ]
      ],
      [
        "Statutory Compliance, Authorization, and Isolation Controls",
        [
          "Ensure all electrical tasks are carried out solely by authorized personnel under the direct supervision of an authorized supervisor.",
          "Strictly follow all statutory regulations outlined in the CEA Regulations 2023.",
          "Do not carry out any work without obtaining a valid Work Permit from an authorized person.",
          "Ensure a proper electrical shutdown is taken and the Lockout/Tagout (LOTO) system is implemented without fail."
        ]
      ],
      [
        "Work Instruction / Procedure",
        [
          "Walk-Around Inspection: Visually inspect each street light structure from all angles for rust, corrosion, or physical damage.",
          "Pole & Fixture Stability: Verify that the lighting pole is structurally stable, firmly grounded, and that the fixture is securely mounted.",
          "Wiring & Connection Inspection: Inspect all wires, cords, and connectors for physical damage, fraying, or looseness.",
          "Electrical Components Verification: Examine internal electrical parts—including driver assemblies, fuses, connectors, and control gear—for faults and replace defective components as needed.",
          "Earthing Integrity: Verify that lighting poles are properly earthed to eliminate electrical shock hazards.",
          "Lamp Cleaning: Clean the lamp glass/cover surface to ensure maximum light output and optical efficiency.",
          "Solar Panel Maintenance: Clean solar panels (where applicable) using a soft cloth and mild detergent to maximize solar absorption.",
          "Illumination Angle Adjustment: Align the mounting position and adjust the beam angle to effectively illuminate target areas and eliminate blind spots.",
          "Troubleshooting & Defect Rectification: Repair or replace broken and deteriorated parts; if a luminaire fails to operate, troubleshoot root causes such as shorted lead wires, burnt-out LED lamp beads, or failed controllers.",
          "Maintenance Record Keeping: Document all inspection findings, maintenance actions, and component replacements—including fixture model, parts replaced, and date of completion."
        ],
        "ol"
      ]
    ],
