          "Functional Testing: Perform individual protection function tests to verify correct operation across all designated application schemes.",
          "Pickup and Trip Time Measurement: Using the relay test set (e.g., OMICRON or Megger), inject secondary current or voltage to determine the pickup threshold and measure operating trip times, confirming they fall strictly within allowable limits.",
          "System-Perspective Testing: Evaluate the relay’s response and performance in coordination with the broader power network to confirm its reliability within the overall protection scheme.",
