          "Smooth Unreeling & Rollers: Carefully unroll the cable using mechanical pullers or rollers spaced at intervals not exceeding 2 meters to avoid excessive tensile stretching.",
          "Sand Cushioning: Bed the bottom of the trench with a layer of clean sand cushion before laying the cable, followed by another sand cushion layer directly over the laid cable.",
          "Bending Radius Control: Ensure all directional turns maintain a smooth bending radius of at least 12 times the overall cable diameter (R ≥ 12D) to safeguard sheath and core integrity.",
          "Trench Spacing: Maintain specified physical clearance and separation between multiple cable runs laid inside the same trench.",
          "Mechanical Protection: Place a continuous layer of protective bricks over the top sand cushion to prevent mechanical penetration or impact damage.",
          "Trench Backfilling: Backfill the trench using excavated soil that has been screened to ensure it is free from stones, boulders, and sharp debris.",
          "End Sealing & Phasing Marks: Seal all exposed cable ends with protective packing to block moisture ingress, and apply distinct phase identification markings.",
          "Post-Laying Testing: Conduct designated post-installation integrity testing (such as OTDR testing for optical fibers or electrical healthiness tests) to confirm cable condition.",
